-- P03 additions run once under seed receipt 3; no P02 records/evidence are rewritten.
-- Derive only new capabilities from still-active source grants. Existing revocations are retained.
SELECT g.workspace_id,g.user_id,g.company_id,CASE g.capability WHEN 'shared.read' THEN 'activity.read' ELSE 'activity.edit' END,g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to
FROM ppo.permission_grants g WHERE g.capability IN ('shared.read','shared.edit') AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;
SELECT g.workspace_id,g.user_id,g.company_id,CASE g.capability WHEN 'shared.edit' THEN 'service.ticket.edit' ELSE 'service.ticket.read' END,g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to
FROM ppo.permission_grants g JOIN ppo.users u ON (u.workspace_id,u.id)=(g.workspace_id,g.user_id)
WHERE u.subject_id IN ('second-company','site-observer','workspace-observer') AND g.capability IN ('shared.read','shared.edit') AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;
SELECT workspace_id,user_id,company_id,'activity.edit',scope_type,scope_id,site_id,valid_from,valid_to FROM ppo.permission_grants WHERE capability='shared.finance.read' AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;
